import {api} from './api-client.js';
import {installBackendUI} from './backend-ui.js';
import {renderWorkspace} from './workspace-ui.js';
import {escapeHTML as e,money as m,icon,link as l,Button as B,field as f,textarea as ta,select as sel,panel as P,table as T,status as badge} from './components.js';

let s={user:null,products:[],shops:[],categories:[],cart:[],cartTotals:{groups:[],subtotal:0,shipping:0,discount:0,total:0},orders:[],groups:[],favorites:[],notifications:[],returns:[],reviews:[],coupons:[],addresses:[],applications:[],users:[],profile:{}};
const selectedSkus={};
let discounts={couponCode:'',shopCoupons:{}},quote=null,catalogData=null,catalogQuery='',renderVersion=0,refreshGeneration=0;
const app=document.querySelector('#app'),go=p=>{location.hash='#/'+p;};
const btn=(label,path)=>B({label,href:path}),action=(label,name,id='',secondary=false)=>B({label,action:name,id,secondary});
let formSequence=0;
const repeatedForms=new Set(['category-rename','shop-status','moderation','return-reject','return-received','refund-record','review']);
const form=(id,body,label='Lưu thay đổi')=>`<form id="${repeatedForms.has(id)?id+'-'+(++formSequence):id}" data-form="${id}" class="market-form">${body}${label?B({label,type:'submit'}):''}</form>`;
const hidden=(name,value)=>`<input type="hidden" name="${e(name)}" value="${e(value)}">`;
const empty=t=>P(t,'<p class="muted">Chưa có dữ liệu.</p>');
const product=id=>s.products.find(p=>p.id===id),shop=id=>s.shops.find(x=>x.id===id);
const money=m,date=v=>new Date(v?.includes('Z')?v:v?.replace(' ','T')+'Z').toLocaleString('vi-VN',{timeZone:'Asia/Bangkok'});
const short=id=>e(id?.slice(0,14)||''),published=p=>p.visible&&p.moderation==='approved'&&shop(p.shopId)?.status==='Đang hoạt động';
const rating=x=>x?.rating?Number(x.rating).toFixed(1)+' ★':'Chưa có đánh giá';
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');setTimeout(()=>el.classList.remove('visible'),4000);}
async function refreshState(){const generation=++refreshGeneration,oldUser=s.user?.id,oldShop=s.shopId;const data=await api('/bootstrap');if(generation!==refreshGeneration)return;Object.assign(s,data);if(oldUser!==s.user?.id){discounts={couponCode:'',shopCoupons:{}};sessionStorage.removeItem('cho-ptit-checkout');}if(s.shopIds?.includes(oldShop))s.shopId=oldShop;quote=null;if(s.user&&s.cart.length){try{const updatedQuote=await api('/checkout/quote',{method:'POST',body:discounts});if(generation!==refreshGeneration)return;quote=updatedQuote;}catch(err){discounts={couponCode:'',shopCoupons:{}};quote=s.cartTotals;toast(err.message);}}catalogData=null;}
function header(){return `<header><div class="utility"><div class="container"><span>SÀN MUA SẮM CHO NGƯỜI MUA & NGƯỜI BÁN</span><div><span>Khám phá các gian hàng trên Chợ PTIT</span>${l('support','Hỗ trợ')}${s.user?l('notifications','Thông báo'+(s.unreadCount?' ('+s.unreadCount+')':'')):''}</div></div></div><div class="container main-header"><a class="brand" href="#/"><b>Chợ PTIT</b><span>MUA SẮM<br>ĐA NGÀNH</span></a><form id="search-form" class="search">${icon('search')}<input name="q" aria-label="Tìm kiếm" placeholder="Tìm sản phẩm hoặc gian hàng..."><button aria-label="Tìm kiếm">↵</button></form><div class="header-actions"><a href="#/favorites" aria-label="Yêu thích">${icon('heart')}<span>Yêu thích</span></a><a href="#/cart" aria-label="Giỏ hàng (${s.cart.reduce((n,x)=>n+x.qty,0)})">${icon('bag-icon')}<span>Giỏ hàng (${s.cart.reduce((n,x)=>n+x.qty,0)})</span></a><a href="#/${s.user?'account':'login'}" aria-label="Tài khoản">${icon('user')}<span>Tài khoản</span></a></div></div><nav class="category-nav"><div class="container">${l('products','Tất cả sản phẩm')}${s.categories.slice(0,4).map(c=>l('products?category='+encodeURIComponent(c),e(c))).join('')}${l(s.user?.role==='seller'?'seller':s.user?.role==='admin'?'admin':'open-shop',s.user?.role==='seller'?'Kênh người bán ↗':s.user?.role==='admin'?'Quản trị sàn ↗':'Bán hàng cùng Chợ PTIT ↗','story-link')}</div></nav></header>`;}
function footer(){return `<footer><div class="container footer-columns"><div><a class="logo" href="#/">Chợ PTIT</a><p>Kết nối người mua và người bán.<br>Khám phá sản phẩm từ nhiều ngành hàng.</p></div>${[['Khám phá',[['products','Tất cả sản phẩm'],['shops','Các gian hàng'],['about','Về Chợ PTIT']]],['Mua sắm',[['orders','Đơn mua'],['addresses','Địa chỉ nhận hàng'],['policies','Vận chuyển & đổi trả']]],['Tài khoản',[['account','Thông tin cá nhân'],['open-shop','Đăng ký gian hàng'],['support','Hướng dẫn sử dụng']]]].map(([title,links])=>`<div><h4>${title}</h4>${links.map(([p,t])=>l(p,t)).join('')}</div>`).join('')}</div><div class="footer-rule"></div><div class="container footer-bottom"><span>© ${new Date().getFullYear()} Chợ PTIT</span><span>Thanh toán khi nhận hàng · COD</span></div></footer>`;}
function page(title,body){return `<main id="main" tabindex="-1" class="container page marketplace"><div class="breadcrumbs">${l('','CHỢ PTIT')} / ${e(title.toUpperCase())}</div>${body.startsWith('<div class="market-detail">')?'':`<h1>${e(title)}</h1>`}${body}</main>`;}
function card(p){const isSaved=s.favorites.includes(p.id);return `<article class="product-card"><div class="product-art">${l('product/'+p.id,`<img src="${e(p.photo||'./assets/'+p.image+'.svg')}" width="240" height="200" alt="${e(p.name)}">`)}<button data-action="favorite" data-id="${e(p.id)}" class="save-product ${isSaved?'saved':''}" aria-label="${isSaved?'Bỏ yêu thích':'Yêu thích'} ${e(p.name)}" aria-pressed="${isSaved}">${icon('heart')}</button></div><div class="product-info">${l('product/'+p.id,e(p.name),'product-name')}<strong>${p.maxPrice>p.price?'Từ ':''}${m(p.price)}</strong>${l('store/'+p.shopId,e(shop(p.shopId)?.name||'Gian hàng'))}<small>${rating(p)}${p.reviewCount?' · '+p.reviewCount+' đánh giá':''}</small>${!p.stock?'<small>Tạm hết hàng</small>':''}</div></article>`;}
const grid=ps=>`<div class="market-products">${ps.map(card).join('')||empty('Chưa tìm thấy sản phẩm')}</div>`;
const shopCard=x=>P(x.name,`<p>${e(x.category)} · ${rating(x)}</p>${btn('Xem gian hàng','store/'+x.id)}`);
function home(){return page('Khám phá Chợ PTIT',`<section class="market-hero"><div><small>NHIỀU GIAN HÀNG · MỘT ĐIỂM MUA SẮM</small><h2>Điều bạn cần,<br>đều có ở Chợ PTIT.</h2><p>Khám phá sản phẩm từ nhiều ngành hàng và những người bán đã được xét duyệt.</p>${btn('Khám phá sản phẩm','products')}</div><aside><h2>Mua sắm an tâm</h2><p>Chọn đúng phân loại · Theo dõi từng đơn hàng</p>${btn('Khám phá gian hàng','shops')}</aside></section><div class="market-categories">${s.categories.map(c=>l('products?category='+encodeURIComponent(c),`<strong>${e(c)}</strong><small>Khám phá →</small>`)).join('')}</div><h2>Sản phẩm đang bán</h2>${grid(s.products.filter(published).slice(0,5))}<h2>Khám phá gian hàng</h2><div class="market-shops">${s.shops.filter(x=>x.status==='Đang hoạt động').slice(0,3).map(shopCard).join('')||empty('Chưa có gian hàng')}</div>`);}
async function catalog(q){const query=q.toString();if(catalogQuery!==query||!catalogData){catalogData=await api('/catalog?'+query);catalogQuery=query;}const result=catalogData;return page('Tất cả sản phẩm',form('filter',`<div class="catalog-search">${f('Tìm sản phẩm hoặc gian hàng','q',q.get('q')||'')}${B({label:'Tìm kiếm',type:'submit'})}</div><div class="catalog-filters">${sel('Ngành hàng','category',['',...s.categories],q.get('category')||'')}${f('Giá từ (đ)','min',q.get('min')||'','number',false,'min="0"')}${f('Giá đến (đ)','max',q.get('max')||'','number',false,'min="0"')}${sel('Sắp xếp','sort',[{value:'',label:'Liên quan'},{value:'asc',label:'Giá tăng dần'},{value:'desc',label:'Giá giảm dần'}],q.get('sort')||'')}${B({label:'Lọc sản phẩm',type:'submit'})}</div>`,'Áp dụng')+`<p class="muted">${result.total} sản phẩm</p>`+grid(result.items)+`<div class="inline-actions">${result.page>1?btn('← Trang trước','products?'+new URLSearchParams({...Object.fromEntries(q),page:result.page-1})):''}<span>Trang ${result.page} / ${Math.max(1,Math.ceil(result.total/result.limit))}</span>${result.page*result.limit<result.total?btn('Trang sau →','products?'+new URLSearchParams({...Object.fromEntries(q),page:result.page+1})):''}</div>`);}
function detail(id){const p=product(id);if(!p||!published(p))return page('Không tìm thấy sản phẩm',empty('Sản phẩm không còn được bán')+btn('Xem sản phẩm khác','products'));const selected=p.skus.find(x=>x.id===selectedSkus[p.id])||p.skus.find(x=>x.stock>0)||p.skus[0],reviews=s.reviews.filter(x=>x.productId===p.id);return page(p.name,`<div class="market-detail"><div class="market-gallery"><img src="${e(p.photo||'./assets/'+(p.image.startsWith('market-')?p.image.replace('market-','market-large-'):p.image)+'.svg')}" alt="${e(p.name)}" width="480" height="400"></div><div class="market-detail-info"><small>${e(p.category)} · ${rating(p)}</small><h1>${e(p.name)}</h1>${l('store/'+p.shopId,e(shop(p.shopId).name)+' ↗')}<strong id="sku-price" class="detail-price">${m(selected.price)}</strong><p>${e(p.description)}</p><p>${e(p.attributes)}</p>${form('add-cart',hidden('productId',p.id)+sel('Phân loại','skuId',p.skus.map(x=>({value:x.id,label:x.label+(x.stock?'':' · Hết hàng')})),selected.id)+f('Số lượng','qty',1,'number',true,`min="1" max="${Math.min(99,selected.stock)}"`)+`<p id="sku-stock" class="muted">Còn ${selected.stock} sản phẩm</p><p>Phí giao hàng: ${m(shop(p.shopId).shipping)}</p><div class="button-row">${B({label:'Thêm vào giỏ hàng',type:'submit',extra:!selected.stock?'disabled':''})}<button type="submit" class="button secondary" name="buy" value="buy" ${!selected.stock?'disabled':''}>Mua ngay</button></div>`,'')}${l('policies','Chính sách mua hàng và đổi trả →')}</div></div>${P('Đánh giá từ người mua',reviews.map(r=>`<article class="review"><strong>${e(r.name)} · ${r.rating} ★</strong><p>${e(r.body)}</p><small>${date(r.date)}</small></article>`).join('')||'<p>Chưa có đánh giá từ đơn hàng đã hoàn thành.</p>')}`);}
function totals(t){return `<div class="summary-line"><span>Tiền hàng</span><strong>${m(t.subtotal)}</strong></div><div class="summary-line"><span>Phí giao hàng</span><strong>${m(t.shipping)}</strong></div><div class="summary-line"><span>Ưu đãi</span><strong>−${m(t.discount)}</strong></div><hr><div class="summary-line"><strong>Tổng thanh toán</strong><strong>${m(t.total)}</strong></div>`;}
function cartView(){if(!s.cart.length)return page('Giỏ hàng',empty('Giỏ hàng đang trống')+btn('Khám phá sản phẩm','products'));const t=quote||s.cartTotals;return page(`Giỏ hàng · ${t.groups.length} gian hàng`,`<div class="split"><div class="market-stack">${t.groups.map(g=>P(g.name,g.items.map(x=>`<div class="market-cart-row"><img src="${e(x.photo||'./assets/'+x.image+'.svg')}" width="80" height="70" alt="${e(x.name)}"><div>${l('product/'+x.id,e(x.name))}<small>${e(x.variant)} · ${m(x.price)}</small>${!x.available?'<small class="error-text">Ngừng bán hoặc không đủ tồn kho</small>':''}</div><div class="qty">${action('−','qty-down',x.skuId,true)}<span>${x.qty}</span>${action('+','qty-up',x.skuId,true)}</div>${action('Xóa','remove',x.skuId,true)}</div>`).join('')+`<p>Phí giao hàng ${m(g.shipping)}</p>`)).join('')}</div>${P('Tổng giỏ hàng',totals(t)+(t.valid?btn('Tiến hành thanh toán','checkout'):'<p class="error-text">Vui lòng xóa hoặc giảm số lượng sản phẩm không còn đủ hàng trước khi thanh toán.</p>'),'summary')}</div>`);}
function checkoutView(){const t=quote||s.cartTotals;if(!s.cart.length||!t.valid)return cartView();const address=s.addresses.find(x=>x.default)||s.addresses[0];return page('Thanh toán nhiều gian hàng',P('Địa chỉ nhận hàng',address?`<label class="field"><span>Chọn địa chỉ</span><select form="checkout" name="addressId">${s.addresses.map(x=>`<option value="${e(x.id)}" ${x.id===address.id?'selected':''}>${e(x.name)} · ${e(x.phone)} · ${e(x.street)}</option>`).join('')}</select></label>${btn('Quản lý địa chỉ','addresses')}`:btn('Thêm địa chỉ','address/new'))+t.groups.map(g=>P(g.name,g.items.map(x=>`<p><strong>${e(x.name)}</strong> · ${e(x.variant)} × ${x.qty} · ${m(x.price*x.qty)}</p>`).join('')+`<p>Phí giao hàng ${m(g.shipping)} · Ưu đãi −${m(g.discount)}</p><label class="field"><span>Ghi chú cho ${e(g.name)}</span><input form="checkout" maxlength="500" name="note-${e(g.shopId)}" placeholder="Không bắt buộc"></label>`)).join('')+P('Ưu đãi',form('coupon',f('Mã ưu đãi sàn','couponCode',discounts.couponCode)+t.groups.map(g=>f('Mã ưu đãi của '+g.name,'shop-'+g.shopId,discounts.shopCoupons[g.shopId]||'')).join(''),'Áp dụng mã'))+P('Thanh toán khi nhận hàng',form('checkout',hidden('payment','COD')+totals(t)+'<p>Thanh toán COD. Mỗi gian hàng có đơn và quá trình giao hàng riêng.</p><label class="check"><input type="checkbox" required>Tôi đã kiểm tra địa chỉ, sản phẩm và đồng ý chính sách mua hàng.</label>','Đặt hàng · '+m(t.total))));}
const accountLinks=[['account','Thông tin cá nhân'],['addresses','Địa chỉ nhận hàng'],['orders','Đơn mua'],['returns','Trả hàng / hoàn tiền'],['favorites','Yêu thích'],['vouchers','Ưu đãi'],['notifications','Thông báo'],['password','Đổi mật khẩu']];
function account(title,body){return page(title,`<div class="account-layout"><aside class="panel account-nav"><h3>${e(s.profile.name)}</h3>${accountLinks.map(([p,t])=>l(p,t)).join('')}${s.user.role==='seller'?l('seller','Kênh người bán'):s.user.role==='admin'?l('admin','Quản trị sàn'):l('open-shop','Đăng ký gian hàng')}${action('Đăng xuất','logout')}</aside><div class="account-content">${body}</div></div>`);}
function orderList(seller=false){const os=s.orders.filter(o=>seller?o.shopId===s.shopId:o.buyerId===s.user.id);return T(['Đơn / gian hàng','Ngày','Tổng thanh toán','Trạng thái',''],os.map(o=>[short(o.id)+'<br><small>'+e(o.name)+'</small>',date(o.date),m(o.total),badge(o.status),l((seller?'seller/order/':'order/')+o.id,'Chi tiết →')]));}
function orderView(id,seller=false){const o=s.orders.find(x=>x.id===id&&(seller?x.shopId===s.shopId:x.buyerId===s.user.id));if(!o)return empty('Không tìm thấy đơn hàng');return P('Đơn '+o.id,`<p>Đơn tổng ${e(o.groupId)} · ${e(o.name)}</p>${badge(o.status)}<p>COD · ${e(o.paymentStatus)}</p>${T(['Sản phẩm / Phân loại','Số lượng','Giá','Ưu đãi','Thành tiền'],o.items.map(x=>[e(x.name)+'<br><small>'+e(x.variant)+' · '+e(x.sku)+'</small>',x.qty,m(x.price),m(x.discount),m(x.price*x.qty-x.discount)]))}${totals(o)}<p>${e(o.customer)} · ${e(o.phone)}<br>${e(o.address)}</p>${o.note?`<p>Ghi chú: ${e(o.note)}</p>`:''}${o.tracking?`<p>Vận đơn: ${e(o.carrier)} · ${e(o.tracking)}</p>`:''}<div class="inline-actions">${!seller&&o.status==='Chờ xác nhận'?action('Hủy đơn','cancel',o.id):''}${!seller&&o.status==='Đang giao'?action('Đã nhận hàng và thanh toán COD','received',o.id):''}${seller&&o.status==='Chờ xác nhận'?action('Xác nhận và chuẩn bị hàng','prepare',o.id):''}</div>${seller&&['Chờ xác nhận','Đang chuẩn bị'].includes(o.status)?`<details><summary>Không thể thực hiện đơn hàng</summary>${form('seller-cancel',hidden('orderId',o.id)+ta('Lý do hủy đơn','reason','',true),'Hủy đơn và thông báo người mua')}</details>`:''}${seller&&o.status==='Đang chuẩn bị'?form('ship-order',hidden('orderId',o.id)+f('Đơn vị giao hàng','carrier','','text',true)+f('Mã vận đơn','tracking','','text',true),'Xác nhận đã gửi hàng'):''}${!seller&&o.status==='Hoàn thành'?o.items.map(x=>P(x.name,`${!s.reviews.some(r=>r.itemId===x.id)?form('review',hidden('itemId',x.id)+sel('Điểm đánh giá','rating',['5','4','3','2','1'])+ta('Đánh giá của bạn','body','',true),'Gửi đánh giá'):'<p>Đã đánh giá sản phẩm.</p>'}${!s.returns.some(r=>r.itemId===x.id)?btn('Yêu cầu trả hàng','return-new/'+x.id):''}`)).join(''):''}${P('Lịch sử đơn hàng',o.history.map(h=>`<p><strong>${e(h.status)}</strong> · ${date(h.date)}<br>${e(h.note)}</p>`).join(''))}`);}
function auth(mode,q){const register=mode==='register';return page(register?'Tạo tài khoản':'Đăng nhập',`<div class="auth-layout">${P('Chào mừng đến Chợ PTIT','<h2>Một tài khoản,<br>nhiều trải nghiệm.</h2><p>Mua sắm đa ngành hoặc đăng ký gian hàng để bắt đầu bán hàng.</p>','auth-intro')}${P(register?'Tạo tài khoản người mua':'Chào mừng trở lại',form('auth',hidden('mode',mode)+(register?f('Họ và tên','name','','text',true):'')+f('Email','email',q.get('email')||'','email',true)+f('Mật khẩu','password','','password',true,'minlength="8" maxlength="128" autocomplete="'+(register?'new-password':'current-password')+'"'),register?'Đăng ký':'Đăng nhập')+l(register?'login':'register',register?'Đã có tài khoản? Đăng nhập':'Chưa có tài khoản? Đăng ký'))}</div>`);}
function returnTable(rows,role='buyer'){
  return T(['Yêu cầu / Đơn','Lý do','Số tiền hàng','Trạng thái','Xử lý'],rows.map(r=>[short(r.id)+'<br>'+short(r.orderId),e(r.reason),m(r.amount),badge(r.status),role==='buyer'?l('return/'+r.id,'Chi tiết →'):role==='seller'?(['Chờ shop xử lý','Chờ sàn giải quyết'].includes(r.status)?action('Chấp nhận trả hàng','return-accept',r.id)+(r.status==='Chờ shop xử lý'?form('return-reject',hidden('id',r.id)+ta('Lý do từ chối','reason','',true),'Từ chối yêu cầu'):''):r.status==='Chờ nhận hàng trả'?form('return-received',hidden('id',r.id)+'<label class="check"><input type="checkbox" name="restock">Hàng đã kiểm tra, đủ điều kiện nhập lại kho</label>','Xác nhận đã nhận hàng trả'):'Đã phản hồi'):(r.status==='Chờ sàn giải quyết'?action('Chấp nhận yêu cầu','return-accept',r.id):r.status==='Chờ hoàn tiền'?form('refund-record',hidden('id',r.id)+f('Chứng từ / mã giao dịch đã hoàn tiền','reference','','text',true)+'<label class="check"><input type="checkbox" required>Tôi xác nhận tiền đã được hoàn cho người mua.</label>','Ghi nhận đã hoàn tiền'):r.refundReference?e(r.refundReference):'Chưa cần xử lý')]));
}
function requireLogin(path){return page('Vui lòng đăng nhập','<p>Đăng nhập để tiếp tục thao tác.</p>'+btn('Đăng nhập','login?next='+encodeURIComponent(path)));}
async function routeView(path,q){
  const [r,a]=path.split('/');
  if(r==='seller'||r==='admin')return renderWorkspace(s,path,{orderList,orderView,returnTable});
  if(['cart','checkout','account','addresses','address','delete-address','orders','order','tracking','returns','return-new','return','notifications','favorites','password','apply-shop','shop-verification','shop-bank','confirmation'].includes(r)&&!s.user)return requireLogin(path);
  switch(r){
    case '':return home();
    case 'products':return catalog(q);
    case 'product':return detail(a);
    case 'shops':return page('Khám phá gian hàng',`<div class="market-shops">${s.shops.filter(x=>x.status==='Đang hoạt động').map(shopCard).join('')||empty('Chưa có gian hàng')}</div>`);
    case 'store':{const x=shop(a);return x&&x.status==='Đang hoạt động'?page(x.name,P(x.name,`<p>${e(x.category)} · ${rating(x)}</p><p>${e(x.description||'')}</p><p>Phí giao hàng mỗi đơn: ${m(x.shipping)}</p>`)+grid(s.products.filter(p=>p.shopId===a&&published(p)))):page('Không tìm thấy gian hàng',btn('Khám phá gian hàng','shops'));}
    case 'cart':return cartView();
    case 'checkout':return checkoutView();
    case 'confirmation':{const g=s.groups.find(x=>x.id===a);return page('Thông tin đặt hàng',g?P('Đặt hàng thành công',`<p>Mã đặt hàng: ${e(g.id)}</p><p>${g.children.length} đơn theo gian hàng · Tổng ${m(g.total)}</p>${btn('Xem đơn mua','orders')}`):empty('Không tìm thấy thông tin đặt hàng'));}
    case 'login':case 'register':return auth(r,q);
    case 'roles':return s.user?account('Tài khoản của bạn',P(s.profile.name,`<p>${e(s.profile.email)}</p><p>Vai trò: ${e(s.user.role)}</p>${action('Đăng xuất','logout')}`)):auth('login',q);
    case 'account':return account('Thông tin cá nhân',P('Hồ sơ',form('profile',f('Họ và tên','name',s.profile.name,'text',true)+f('Email','email',s.profile.email,'email',true)+f('Số điện thoại','phone',s.profile.phone,'tel',true))));
    case 'password':return account('Đổi mật khẩu',P('Mật khẩu',form('password',f('Mật khẩu hiện tại','currentPassword','','password',true)+f('Mật khẩu mới','password','','password',true,'minlength="8" maxlength="128"')+f('Nhập lại mật khẩu','confirm','','password',true))));
    case 'addresses':return account('Địa chỉ nhận hàng',s.addresses.map(x=>P(x.name,`<p>${e(x.phone)} · ${e(x.street)}</p>${x.default?badge('Mặc định'):action('Đặt mặc định','default-address',x.id)}<div class="inline-actions">${btn('Chỉnh sửa','address/'+x.id)}${btn('Xóa','delete-address/'+x.id)}</div>`)).join('')+btn('Thêm địa chỉ','address/new'));
    case 'address':{const x=s.addresses.find(x=>x.id===a)||{};return page('Địa chỉ nhận hàng',P('Thông tin người nhận',form('address',hidden('id',x.id||'')+f('Người nhận','name',x.name||'','text',true)+f('Số điện thoại','phone',x.phone||'','tel',true)+ta('Địa chỉ chi tiết','street',x.street||'',true))));}
    case 'delete-address':return page('Xóa địa chỉ',P('Xác nhận xóa','<p>Địa chỉ sẽ được xóa khỏi danh sách nhận hàng. Địa chỉ của các đơn đã đặt vẫn được giữ lại.</p>'+action('Xác nhận xóa','delete-address',a)+btn('Quay lại','addresses')));
    case 'orders':return account('Đơn mua của tôi',orderList());
    case 'order':case 'tracking':return account(r==='tracking'?'Theo dõi đơn hàng':'Chi tiết đơn hàng',orderView(a));
    case 'favorites':return account('Sản phẩm yêu thích',grid(s.products.filter(p=>published(p)&&s.favorites.includes(p.id))));
    case 'vouchers':return page('Ưu đãi đang áp dụng',s.coupons.filter(c=>c.enabled&&c.start<=s.businessDate).map(c=>P(c.code,`<p>${e(shop(c.shopId)?.name||'Ưu đãi sàn')} · Giảm ${m(c.amount)} khi tiền hàng từ ${m(c.minimum)}</p><p>Áp dụng đến ${e(c.end)}, trong giới hạn lượt sử dụng.</p>${btn('Mua sắm','products')}`)).join('')||empty('Hiện chưa có ưu đãi'));
    case 'notifications':return account('Thông báo',s.notifications.map(n=>P(n.read?'Đã đọc':'Thông báo mới',`<p>${e(n.text)}</p><small>${date(n.date)}</small>${btn('Xem chi tiết',n.path)}`)).join('')+(s.notifications.length?action('Đánh dấu đã đọc','read'):'')||empty('Chưa có thông báo'));
    case 'returns':return account('Trả hàng / hoàn tiền',returnTable(s.returns.filter(x=>x.buyerId===s.user.id)));
    case 'return-new':{const o=s.orders.find(o=>o.buyerId===s.user.id&&o.items.some(x=>x.id===a)),item=o?.items.find(x=>x.id===a);return page('Yêu cầu trả hàng',item?P(item.name,form('return',hidden('itemId',item.id)+sel('Lý do','reason',['Sản phẩm lỗi','Sai sản phẩm','Không đúng mô tả','Thiếu hàng'])+ta('Mô tả tình trạng','description','',true)+`<p>Trả toàn bộ ${item.qty} sản phẩm thuộc phân loại ${e(item.variant)}. Tiền hàng sau ưu đãi: ${m(item.price*item.qty-item.discount)}. Không bao gồm phí giao hàng.</p>`,'Gửi yêu cầu')):empty('Không tìm thấy sản phẩm đã mua'));}
    case 'return':{const x=s.returns.find(x=>x.id===a&&x.buyerId===s.user.id);return page('Chi tiết yêu cầu',x?P(x.id,`<p>${e(x.reason)}</p><p>${e(x.description)}</p><p>Tiền hàng: ${m(x.amount)}</p>${badge(x.status)}${['Chờ shop xử lý','Shop từ chối'].includes(x.status)?action('Nhờ sàn giải quyết','dispute',x.id):''}${x.refundReference?`<p>Chứng từ hoàn tiền: ${e(x.refundReference)}</p>`:''}${(x.history||[]).map(h=>`<p><strong>${e(h.status)}</strong> · ${date(h.date)}<br>${e(h.note)}</p>`).join('')}`):empty('Không tìm thấy yêu cầu'));}
    case 'open-shop':return page('Bán hàng cùng Chợ PTIT',P('Mở gian hàng','<p>Đăng ký hồ sơ gian hàng. Sau khi được quản trị phê duyệt, bạn có thể đăng sản phẩm và xử lý đơn mua.</p>'+btn('Đăng ký gian hàng','apply-shop')));
    case 'apply-shop':{const x=s.applications.find(x=>x.userId===s.user.id&&x.status==='Cần bổ sung')||{};return page('Đăng ký gian hàng',P('1. Thông tin gian hàng',(x.reason?`<p class="notice">Yêu cầu bổ sung: ${e(x.reason)}</p>`:'')+form('application',hidden('id',x.id||'')+f('Tên gian hàng','name',x.name||'','text',true)+f('Chủ sở hữu','owner',x.owner||s.profile.name,'text',true)+sel('Ngành hàng','category',s.categories,x.category||''),'Tiếp tục')));}
    case 'shop-verification':return page('Thông tin người bán',P('2. Chủ sở hữu',form('verification',f('Họ tên pháp lý','legalName',s.draftApplication?.legalName||'','text',true),'Tiếp tục')));
    case 'shop-bank':return page('Thông tin nhận tiền',P('3. Tài khoản của người bán',form('bank',f('Ngân hàng','bank','','text',true)+f('Số tài khoản','number','','text',true),'Gửi hồ sơ xét duyệt')));
    case 'shop-pending':return page('Hồ sơ mở gian hàng',s.applications.filter(x=>x.userId===s.user.id).map(x=>P(x.name,`<p>${e(x.status)}</p>${x.reason?`<p>${e(x.reason)}</p>`:''}${x.status==='Cần bổ sung'?btn('Bổ sung hồ sơ','apply-shop'):''}`)).join('')||empty('Chưa có hồ sơ'));
    case 'about':return page('Về Chợ PTIT',P('Sàn mua sắm đa ngành','<p>Chợ PTIT kết nối người mua với các gian hàng. Người bán quản lý sản phẩm và xử lý đơn trong phạm vi gian hàng của mình.</p>'));
    case 'policies':return page('Mua hàng, vận chuyển và đổi trả',P('Quy trình giao dịch','<p>Thanh toán COD khi nhận hàng. Phí vận chuyển được tính riêng từng gian hàng và hiển thị trước khi đặt.</p><p>Có thể hủy khi shop chưa xác nhận đơn. Sau khi shop gửi hàng, theo dõi đơn vị giao hàng và mã vận đơn trong chi tiết đơn mua.</p><p>Chỉ xác nhận đã nhận hàng sau khi nhận sản phẩm và thanh toán. Có thể yêu cầu trả hàng trong 7 ngày từ khi xác nhận nhận hàng; yêu cầu áp dụng cho toàn bộ số lượng của một phân loại trong đơn. Số tiền hàng được tính sau ưu đãi, không bao gồm phí giao hàng.</p><p>Việc hoàn tiền được ghi nhận theo chứng từ sau khi người bán nhận hàng trả và quản trị xác minh.</p>'));
    case 'support':return page('Hướng dẫn sử dụng',P('Mua hàng và quản lý tài khoản','<p>Tìm sản phẩm, chọn phân loại, thêm vào giỏ và kiểm tra địa chỉ trước khi đặt hàng. Theo dõi giao hàng, gửi đánh giá hoặc yêu cầu trả hàng trong mục Đơn mua.</p><p>Người bán đăng ký gian hàng và chờ xét duyệt. Thông báo xử lý hồ sơ, đơn hàng và trả hàng nằm trong mục Thông báo.</p>'+btn('Chính sách giao dịch','policies')));
    default:return page('Không tìm thấy trang',btn('Về trang chủ',''));
  }
}
async function render(){const version=++renderVersion,[path,query='']=location.hash.replace(/^#\/?/,'').split('?');try{const content=await routeView(path,new URLSearchParams(query));if(version!==renderVersion)return;app.innerHTML=path.startsWith('seller')||path.startsWith('admin')?content:header()+content+footer();document.title='Chợ PTIT · '+(app.querySelector('h1')?.textContent||'Mua sắm đa ngành');window.scrollTo(0,0);}catch(err){if(version!==renderVersion)return;app.innerHTML=header()+page('Không thể tải dữ liệu',`<p>${e(err.message)}</p>${action('Thử lại','retry')}`)+footer();}}
async function perform(work,button){if(button?.disabled)return;try{if(button)button.disabled=true;await work();}catch(err){toast(err.message||'Không thể kết nối máy chủ.');if(err.status===401){await refreshState();go('login');}else if(err.status===409){await refreshState();await render();}}finally{if(button)button.disabled=false;}}
function checkoutKey(body){const signature=JSON.stringify(body);let cached;try{cached=JSON.parse(sessionStorage.getItem('cho-ptit-checkout'));}catch{}if(!cached||cached.signature!==signature){cached={signature,key:crypto.randomUUID()};sessionStorage.setItem('cho-ptit-checkout',JSON.stringify(cached));}return cached.key;}
document.addEventListener('submit',event=>{
  const el=event.target,formId=el.dataset.form||el.getAttribute('id'),handled=['search-form','filter','add-cart','coupon','checkout','ship-order','seller-cancel','review','return','return-received','return-reject','refund-record','shop-status','create-coupon','category-rename','moderation','application','verification'];
  if(!handled.includes(formId))return;event.preventDefault();const d=Object.fromEntries(new FormData(el));
  perform(async()=>{
    if(formId==='search-form'){go('products?q='+encodeURIComponent(d.q));return;}
    if(formId==='filter'){go('products?'+new URLSearchParams(d));return;}
    if(formId==='application'){s.draftApplication=d;go('shop-verification');return;}
    if(formId==='verification'){if(!s.draftApplication?.name){go('apply-shop');return;}Object.assign(s.draftApplication,d);go('shop-bank');return;}
    if(formId==='add-cart'){if(!s.user){go('login?next='+encodeURIComponent('product/'+d.productId));return;}await api('/cart/items',{method:'POST',body:{skuId:d.skuId,qty:Number(d.qty)}});await refreshState();if(event.submitter?.value==='buy')go('checkout');else{await render();toast('Đã thêm vào giỏ hàng.');}return;}
    if(formId==='coupon'){const candidate={couponCode:d.couponCode.trim(),shopCoupons:Object.fromEntries(Object.entries(d).filter(([k])=>k.startsWith('shop-')).map(([k,v])=>[k.slice(5),v.trim()]))};quote=await api('/checkout/quote',{method:'POST',body:candidate});discounts=candidate;await render();toast('Đã áp dụng ưu đãi.');return;}
    if(formId==='checkout'){const body={addressId:d.addressId,quoteVersion:(quote||s.cartTotals).version,payment:'COD',...discounts,notes:Object.fromEntries(Object.entries(d).filter(([k])=>k.startsWith('note-')).map(([k,v])=>[k.slice(5),v]))};const result=await api('/checkout',{method:'POST',body,headers:{'Idempotency-Key':checkoutKey(body)}});sessionStorage.removeItem('cho-ptit-checkout');await refreshState();go('confirmation/'+result.id);return;}
    if(formId==='ship-order'){const o=s.orders.find(x=>x.id===d.orderId);await api('/seller/orders/'+d.orderId,{method:'PATCH',body:{status:'Đang giao',version:o.version,carrier:d.carrier,tracking:d.tracking}});}
    if(formId==='seller-cancel'){const o=s.orders.find(x=>x.id===d.orderId);await api('/seller/orders/'+o.id,{method:'PATCH',body:{status:'Đã hủy',version:o.version,reason:d.reason}});}
    if(formId==='review')await api('/reviews',{method:'POST',body:{itemId:d.itemId,rating:Number(d.rating),body:d.body}});
    if(formId==='return'){await api('/returns',{method:'POST',body:d});await refreshState();go('returns');return;}
    if(formId==='return-received')await api('/returns/'+d.id,{method:'PATCH',body:{action:'returned',restock:d.restock==='on'}});
    if(formId==='return-reject')await api('/returns/'+d.id,{method:'PATCH',body:{action:'reject',reason:d.reason}});
    if(formId==='refund-record')await api('/returns/'+d.id,{method:'PATCH',body:{action:'refunded',reference:d.reference}});
    if(formId==='shop-status')await api('/admin/shops/'+d.shopId,{method:'PATCH',body:{status:d.status,reason:d.reason}});
    if(formId==='create-coupon')await api('/admin/coupons',{method:'POST',body:{...d,amount:Number(d.amount),minimum:Number(d.minimum),maxUses:Number(d.maxUses)}});
    if(formId==='category-rename')await api('/admin/categories/'+encodeURIComponent(d.oldName),{method:'PUT',body:{name:d.name}});
    if(formId==='moderation')await api('/admin/products/'+d.productId,{method:'PATCH',body:{moderation:d.moderation,reason:d.reason}});
    await refreshState();await render();toast('Đã lưu thay đổi.');
  },event.submitter);
});
document.addEventListener('click',event=>{
  if(event.target.closest('.skip')){event.preventDefault();document.querySelector('main')?.focus();return;}
  const b=event.target.closest('[data-action]');if(!b)return;const {action:act,id}=b.dataset;
  if(!['favorite','qty-up','qty-down','remove','cancel','received','prepare','read','dispute','return-accept','toggle-coupon','delete-category','retry'].includes(act))return;
  event.preventDefault();perform(async()=>{
    if(act==='retry'){await refreshState();await render();return;}
    if(!s.user){go('login');return;}
    if(act==='favorite')await api('/favorites/'+id,{method:s.favorites.includes(id)?'DELETE':'PUT',body:{}});
    if(['qty-up','qty-down','remove'].includes(act)){const x=s.cart.find(x=>x.skuId===id);if(!x)return;const qty=x.qty+(act==='qty-up'?1:-1);await api('/cart/items/'+id,{method:act==='remove'||qty<1?'DELETE':'PATCH',body:qty>0?{qty}:{}});}
    if(act==='cancel'||act==='received')await api('/orders/'+id+'/'+act,{method:'POST',body:{}});
    if(act==='prepare'){const o=s.orders.find(o=>o.id===id);await api('/seller/orders/'+id,{method:'PATCH',body:{status:'Đang chuẩn bị',version:o.version}});}
    if(act==='read')await api('/notifications/read',{method:'POST',body:{}});
    if(act==='dispute'||act==='return-accept')await api('/returns/'+id,{method:'PATCH',body:{action:act==='dispute'?'dispute':'accept'}});
    if(act==='toggle-coupon'){const c=s.coupons.find(x=>x.code===id);await api('/admin/coupons/'+encodeURIComponent(id),{method:'PATCH',body:{enabled:!c.enabled}});}
    if(act==='delete-category')await api('/admin/categories/'+encodeURIComponent(id),{method:'DELETE',body:{}});
    await refreshState();await render();toast('Đã cập nhật.');
  },b);
});
document.addEventListener('change',event=>{
  const el=event.target;if(el.id==='shop-select'){s.shopId=el.value;render();return;}
  if(el.name==='skuId'&&el.closest('#add-cart')){const fd=new FormData(el.closest('form')),p=product(fd.get('productId')),sku=p?.skus.find(x=>x.id===el.value);if(!sku)return;selectedSkus[p.id]=sku.id;document.querySelector('#sku-price').textContent=m(sku.price);document.querySelector('#sku-stock').textContent='Còn '+sku.stock+' sản phẩm';const qty=el.closest('form').querySelector('[name="qty"]');qty.max=Math.min(99,sku.stock);qty.value=1;for(const b of el.closest('form').querySelectorAll('button[type="submit"]'))b.disabled=!sku.stock;}
});
installBackendUI({state:()=>s,refresh:refreshState,render,go,toast});
window.addEventListener('hashchange',async()=>{try{await refreshState();await render();}catch(err){app.innerHTML=header()+page('Không thể tải dữ liệu',`<p>${e(err.message)}</p>${action('Thử lại','retry')}`)+footer();}});
try{await refreshState();await render();}catch{app.innerHTML=page('Không kết nối được máy chủ','<p>Vui lòng kiểm tra kết nối và thử lại.</p>'+action('Thử lại','retry'));}
